namespace psx::situation {namespace {
void require(bool v,const char* reason){if(!v)throw std::invalid_argument(reason);}
int integer(std::string_view s){int v{};auto r=std::from_chars(s.data(),s.data()+s.size(),v);require(r.ec==std::errc{}&&r.ptr==s.data()+s.size(),"invalid native integer");return v;}
std::vector<std::string_view> parts(std::string_view value){std::vector<std::string_view> out;for(;;){auto p=value.find(';');out.push_back(value.substr(0,p));if(p==value.npos)return out;value.remove_prefix(p+1);}}
double number(std::string_view s){double v{};auto r=std::from_chars(s.data(),s.data()+s.size(),v);require(r.ec==std::errc{}&&r.ptr==s.data()+s.size()&&std::isfinite(v),"invalid native number");return v;}
// Audited durable FMC keys. Failure triggers, display text, keypress events,
// autoflight controls and actual fuel quantities are deliberately not selected.
constexpr std::string_view fmc_keys[]={"FmcMem1","FmcEicas","FltTime","Anp","DepArrSel0","DepArrSel1","DepArrSel2","DepArr","FmcPerfFac","FmcCrossload","FmcNavDbDates","FmcNavInhib","FmcPosBias","FmcPosBiasMode","FmcPosInit","FmcAppRef","FmcThrSet","FmcLegStep","FmcRteViAcMo","FmcRtePgsOf","FmcRte0","FmcRte1","FmcRte2","FmcRteApts0","FmcRteApts1","FmcRteApts2","FmcDepRwys0","FmcDepRwys1","FmcDepRwys2","FmcArrRwys0","FmcArrRwys1","FmcArrRwys2","FmcRtePredA","FmcRtePredM","FmcVnavX","FmcDesFoca","FmcOffpath","FmcPerfInit","FmcTkofRef","FmcProg1","FmcFixInfo","FmcHold","FmcFltNo","FmcScrPads","FuelFmc","FmcAirlPol","FmcMiscPgsOf","FmcFixInfoNg"};
struct Definition {const char* key;const char* id;const char* label;int lo,hi;const char* choices;int mask;};
constexpr Definition definitions[]={
 {"FlapLever","flap_lever","Flap lever",0,6,"UP|1|5|10|20|25|30",0},
 {"GearLever","gear_lever","Gear lever",1,3,"UP|OFF|DOWN",0},
 {"FuelCutoff1","fuel_cutoff_1","Engine 1 fuel control",0,7,"CUTOFF|RUN",1},
 {"FuelCutoff2","fuel_cutoff_2","Engine 2 fuel control",0,7,"CUTOFF|RUN",1},
 {"FuelCutoff3","fuel_cutoff_3","Engine 3 fuel control",0,7,"CUTOFF|RUN",1},
 {"FuelCutoff4","fuel_cutoff_4","Engine 4 fuel control",0,7,"CUTOFF|RUN",1},
 {"EngStartSw1","engine_start_1","Engine start 1",0,8199,"PUSHED|PULLED",1},
 {"EngStartSw2","engine_start_2","Engine start 2",0,8199,"PUSHED|PULLED",1},
 {"EngStartSw3","engine_start_3","Engine start 3",0,8199,"PUSHED|PULLED",1},
 {"EngStartSw4","engine_start_4","Engine start 4",0,8199,"PUSHED|PULLED",1}
};
constexpr std::string_view push_keys[]={"HydEng1","HydEng2","HydEng3","HydEng4","UtilL","UtilR","Battery","BusTie1","BusTie2","BusTie3","BusTie4","GenCont1","GenCont2","GenCont3","GenCont4","Eec1","Eec2","Eec3","Eec4","FuelXfeed1","FuelXfeed2","FuelXfeed3","FuelXfeed4","FuelMain1Fwd","FuelMain1Aft","FuelMain2Fwd","FuelMain2Aft","FuelMain3Fwd","FuelMain3Aft","FuelMain4Fwd","FuelMain4Aft","FuelOvrd2Fwd","FuelOvrd2Aft","FuelOvrd3Fwd","FuelOvrd3Aft","FuelAuxL","FuelAuxR","FuelCtrL","FuelCtrR","FuelStabL","FuelStabR","FuelXfer","IgnitSwCon","AutoStart","OutflowManL","OutflowManR","TrimAir","IslnValveL","IslnValveR","ApuValve","EngBleed1","EngBleed2","EngBleed3","EngBleed4"};
// Range-qualified native detent codes are useful checklist data even where a
// panel label has not been qualified. No guessed AUTO/OFF/ON names are supplied.
constexpr Definition detents[]={
 {"HydDem1","HydDem1","Hydraulic demand 1",0,3,"",0},{"HydDem2","HydDem2","Hydraulic demand 2",1,3,"",0},{"HydDem3","HydDem3","Hydraulic demand 3",1,3,"",0},{"HydDem4","HydDem4","Hydraulic demand 4",0,3,"",0},
 {"PackSel1","PackSel1","Pack selector 1",0,3,"",0},{"PackSel2","PackSel2","Pack selector 2",0,3,"",0},{"PackSel3","PackSel3","Pack selector 3",0,3,"",0},
 {"CabAltContSel","CabAltContSel","Cabin altitude controller selector",0,2,"",0},{"ApuStart","ApuStart","APU start selector",0,2,"",0},
 {"IgnitSelStby","IgnitSelStby","Standby ignition selector",0,2,"",0},{"IgnitSelAuto","IgnitSelAuto","Auto ignition selector",0,3,"",0},{"Autobr","Autobr","Autobrake selector",0,7,"",0},{"OutflowTogg","OutflowTogg","Outflow toggle",-1,1,"",0},{"ParkBrkLev","ParkBrkLev","Parking brake lever",0,1,"",0}
};
constexpr std::string_view raw_keys[]={"AltnStabTrim","StabTrimCp","StabTrimFo","Flaps","FlapTime","EnginesInit","StabTrim","AilTrim","RudTrim"};
std::string choice(std::string_view s,int index){std::size_t start{};for(int i=0;i<index;++i){start=s.find('|',start);require(start!=s.npos,"detent table");++start;}auto end=s.find('|',start);return std::string(s.substr(start,end==s.npos?s.size()-start:end-start));}
void put(std::vector<std::uint8_t>& b,std::uint32_t v,unsigned count){for(unsigned i=0;i<count;++i)b.push_back(static_cast<std::uint8_t>(v>>(8*i)));}
void text(std::vector<std::uint8_t>& b,std::string_view s){b.insert(b.end(),s.begin(),s.end());}
struct Reader {std::span<const std::uint8_t> b;std::size_t p{};std::uint32_t get(unsigned n){require(n<=4&&p+n<=b.size(),"truncated FMC");std::uint32_t v{};for(unsigned i=0;i<n;++i)v|=std::uint32_t(b[p++])<<(8*i);return v;}std::string str(std::size_t n){require(p+n<=b.size(),"truncated FMC string");std::string v(reinterpret_cast<const char*>(b.data()+p),n);p+=n;return v;}Hash hash(){require(p+32<=b.size(),"truncated FMC hash");Hash h{};std::copy_n(b.data()+p,32,h.data());p+=32;return h;}};
}
Hash sha256(std::span<const std::uint8_t> b){require(b.size()<=max_artifact,"artifact size");BCRYPT_ALG_HANDLE a{};BCRYPT_HASH_HANDLE h{};Hash out{};if(BCryptOpenAlgorithmProvider(&a,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0)throw std::runtime_error("SHA256 provider");auto status=BCryptCreateHash(a,&h,nullptr,0,nullptr,0,0);if(status>=0)status=BCryptHashData(h,const_cast<PUCHAR>(b.data()),static_cast<ULONG>(b.size()),0);if(status>=0)status=BCryptFinishHash(h,out.data(),32,0);if(h)BCryptDestroyHash(h);BCryptCloseAlgorithmProvider(a,0);if(status<0)throw std::runtime_error("SHA256 failure");return out;}
std::string hex(Hash h){constexpr char digits[]="0123456789abcdef";std::string r(64,'0');for(std::size_t i=0;i<h.size();++i){r[i*2]=digits[h[i]>>4];r[i*2+1]=digits[h[i]&15];}return r;}
Snapshot inspect(std::span<const std::uint8_t> bytes){require(!bytes.empty()&&bytes.size()<=max_artifact,"situation size");std::string_view s(reinterpret_cast<const char*>(bytes.data()),bytes.size());require(s.find('\0')==s.npos,"NUL in situation");Snapshot r;r.hash=sha256(bytes);std::size_t pos{},line{};bool description_done=false,ended=false;while(pos<s.size()){auto end=s.find('\n',pos);if(end==s.npos)end=s.size();auto v=s.substr(pos,end-pos);if(!v.empty()&&v.back()=='\r')v.remove_suffix(1);require(v.size()<=max_line,"situation line size");if(line==0)require(v=="[Aerowinx Precision Simulator - Situation]","situation header");else if(line==1){require(v.starts_with("[Version ")&&v.ends_with(']'),"situation version");r.version=std::string(v.substr(9,v.size()-10));require(!r.version.empty()&&r.version.size()<=64,"version length");}else if(v=="^-^-^-^ End of description ^-^-^-^")description_done=true;else if(description_done&&v=="[End of file]"){require(!ended,"duplicate situation terminator");ended=true;}else if(description_done&&!v.empty()){require(!ended,"data after situation terminator");auto equal=v.find('=');require(equal!=v.npos&&equal>0&&equal<=64,"situation field");auto key=v.substr(0,equal);require(std::all_of(key.begin(),key.end(),[](unsigned char c){return (c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='_';}),"situation key");require(r.fields.size()<2048,"situation field count");require(r.fields.emplace(std::string(key),std::string(v.substr(equal+1))).second,"duplicate situation field");}++line;pos=end+1;}require(description_done&&ended&&!r.fields.empty(),"incomplete situation");return r;}
void validate_native(const Snapshot& r){for(auto key:{"StartPiBaHeAlVsTasYw","EnginesInit","FlapLever","GearLever","SimPaused"})require(r.fields.contains(key),"missing native initialization field");auto flap=integer(r.fields.at("FlapLever"));require(flap>=0&&flap<=6,"flap detent");auto gear=integer(r.fields.at("GearLever"));require(gear>=1&&gear<=3,"gear detent");auto pause=integer(r.fields.at("SimPaused"));require(pause>=0&&pause<=3,"pause mask");auto pose=parts(r.fields.at("StartPiBaHeAlVsTasYw"));require(pose.size()==11,"native pose initialization length");for(std::size_t i=0;i<pose.size();++i){if(i==8||i==9)number(pose[i]);else integer(pose[i]);}require(integer(pose[0])>=0&&integer(pose[0])<=1,"native initialization flag");require(std::abs(number(pose[8]))<=1.570796326794897&&std::abs(number(pose[9]))<=3.141592653589794,"native reference range");auto engine=parts(r.fields.at("EnginesInit"));require(engine.size()==29&&engine[8].size()==4,"engine initialization length");for(std::size_t i=0;i<engine.size();++i)if(i!=8)integer(engine[i]);}
std::vector<Setting> cockpit_settings(const Snapshot& r){
 std::vector<Setting> out;
 auto add=[&](const Definition& d){auto f=r.fields.find(d.key);if(f==r.fields.end())return;Setting v{d.id,d.label,d.key,f->second,f->second,"native detent","",false};try{int code=integer(f->second);if(code>=d.lo&&code<=d.hi&&(!d.mask||(code&~d.hi)==0)){int index=d.mask?(code&d.mask):code-d.lo;v.value=*d.choices?choice(d.choices,index):std::to_string(code);v.display=*d.choices?v.value:"Native detent "+v.value;v.qualified=true;}}catch(const std::invalid_argument&){}out.push_back(std::move(v));};
 for(const auto& d:definitions)add(d);for(const auto& d:detents)add(d);
 for(auto key:push_keys){auto f=r.fields.find(key);if(f==r.fields.end())continue;Setting v{std::string(key),std::string(key),std::string(key),f->second,f->second,"mechanical selection","",false};try{int code=integer(f->second);if(code>=0&&(code&~8703)==0){v.value=(code&1)?"PUSHED":"RELEASED";v.display=v.value;v.qualified=true;}}catch(const std::invalid_argument&){}out.push_back(std::move(v));}
 for(auto key:{"StabTrimCut2","StabTrimCut3"}){auto f=r.fields.find(key);if(f==r.fields.end())continue;Setting v{key,key,key,f->second,f->second,"mechanical selection","",false};try{int code=integer(f->second);if(code>=0&&code<=7&&(code&6)!=6){v.value=(code&4)?"AUTO":(code&2)?"ON":"OFF";v.display=v.value;v.qualified=true;}}catch(const std::invalid_argument&){}out.push_back(std::move(v));}
 for(auto key:raw_keys){auto f=r.fields.find(key);if(f!=r.fields.end())out.push_back({std::string(key),std::string(key),std::string(key),f->second,f->second,"native encoded","",false});}
 if(auto f=r.fields.find("Tla");f!=r.fields.end()){std::string_view rest=f->second;for(int i=1;i<=4;++i){auto pos=rest.find(';');auto raw=rest.substr(0,pos);Setting v{"thrust_lever_"+std::to_string(i),"Signed forward/reverse thrust lever "+std::to_string(i),"Tla",std::string(raw),std::string(raw),"hundredths of a degree","",false};try{int code=integer(raw);if(code>=-8925&&code<=5000){v.value=std::to_string(code);v.display=std::to_string(code/100.0);v.qualified=true;}}catch(const std::invalid_argument&){}out.push_back(std::move(v));if(pos==rest.npos)break;rest.remove_prefix(pos+1);}}
 return out;
}
std::vector<Comparison> compare(const Snapshot& r,const std::map<std::string,std::string,std::less<>>& physical){std::vector<Comparison> out;for(auto v:cockpit_settings(r)){Match state=Match::unobserved;auto f=physical.find(v.id);if(v.qualified&&f!=physical.end())state=f->second==v.value?Match::match:Match::mismatch;out.push_back({std::move(v),state});}return out;}
bool fmc_field(std::string_view key)noexcept{return std::find(std::begin(fmc_keys),std::end(fmc_keys),key)!=std::end(fmc_keys);}
FmcSnapshot extract_fmc(const Snapshot& r,Hash source){FmcSnapshot f;f.source_version=r.version;f.parent_hash=r.hash;f.source_jar_hash=source;for(const auto& [k,v]:r.fields)if(fmc_field(k))f.fields.emplace(k,v);require(f.fields.contains("FmcMem1")&&f.fields.contains("FmcRte0")&&f.fields.contains("FmcPerfInit"),"incomplete FMC memory");return decode_fmc(encode_fmc(f));}
std::vector<std::uint8_t> encode_fmc(const FmcSnapshot& f){require(!f.source_version.empty()&&f.source_version.size()<=64&&f.source_version.find_first_of("\r\n\0",0,3)==f.source_version.npos&&!f.fields.empty()&&f.fields.size()<=64,"FMC metadata");std::vector<std::uint8_t> payload;put(payload,static_cast<std::uint32_t>(f.source_version.size()),2);text(payload,f.source_version);put(payload,static_cast<std::uint32_t>(f.fields.size()),2);for(const auto& [k,v]:f.fields){require(fmc_field(k)&&k.size()<=64&&v.size()<=max_line&&v.find_first_of("\r\n\0",0,3)==v.npos,"FMC field");put(payload,static_cast<std::uint32_t>(k.size()),2);put(payload,static_cast<std::uint32_t>(v.size()),4);text(payload,k);text(payload,v);}require(payload.size()+112<=max_artifact,"FMC size");std::vector<std::uint8_t> out{'F','M','C','1'};put(out,1,2);put(out,0,2);put(out,static_cast<std::uint32_t>(payload.size()),4);put(out,112,4);for(auto h:{f.parent_hash,f.source_jar_hash,sha256(payload)})out.insert(out.end(),h.begin(),h.end());out.insert(out.end(),payload.begin(),payload.end());return out;}
FmcSnapshot decode_fmc(std::span<const std::uint8_t> b){require(b.size()>=112&&b.size()<=max_artifact,"FMC size");Reader r{b};require(r.str(4)=="FMC1"&&r.get(2)==1&&r.get(2)==0,"FMC version");auto length=r.get(4);require(r.get(4)==112&&length==b.size()-112,"FMC framing");FmcSnapshot f;f.parent_hash=r.hash();f.source_jar_hash=r.hash();f.payload_hash=r.hash();require(f.payload_hash==sha256(b.subspan(112)),"FMC checksum");auto n=r.get(2);require(n>0&&n<=64,"FMC version length");f.source_version=r.str(n);require(f.source_version.find_first_of("\r\n\0",0,3)==f.source_version.npos,"FMC version characters");auto count=r.get(2);require(count>0&&count<=64,"FMC field count");for(unsigned i=0;i<count;++i){auto kn=r.get(2),vn=r.get(4);require(kn>0&&kn<=64&&vn<=max_line,"FMC lengths");auto k=r.str(kn),v=r.str(vn);require(fmc_field(k)&&v.find_first_of("\r\n\0",0,3)==v.npos&&f.fields.emplace(k,v).second,"FMC field");}require(r.p==b.size()&&f.fields.contains("FmcMem1")&&f.fields.contains("FmcRte0")&&f.fields.contains("FmcPerfInit"),"FMC completeness");return f;}
}
